class Base {
    int data;
public:
    Base(int v) : data(v) {}
    Base(std::string s) : data(s.length()) {}
};

class Derived : public Base {
public:
    // Inherit constructors from Base (C++11 feature)
    using Base::Base;

    // Can still define new constructors
    Derived(double d) : Base(int(d)) {}
};

// Usage implied:
// Derived d1(10);
// Derived d2("Hello");
